import java.net.http.*; import java.net.*; import java.time.*;
public class HttpTest { public static void main(String[] a) throws Exception { String u="https://cdn.modrinth.com/data/u6dRKJwZ/4a3f18ac0d096c9f8e9176984c44be4e58f94c89_96.webp"; for(var v: new HttpClient.Version[]{HttpClient.Version.HTTP_1_1,HttpClient.Version.HTTP_2}) { HttpClient c=HttpClient.newBuilder().version(v).connectTimeout(Duration.ofSeconds(20)).build(); long t=System.currentTimeMillis(); try { var r=c.send(HttpRequest.newBuilder(URI.create(u)).header("User-Agent","MCLite/1.0").GET().build(),HttpResponse.BodyHandlers.ofByteArray()); System.out.println(v+" "+r.statusCode()+" "+r.body().length+" "+(System.currentTimeMillis()-t)); } catch(Exception e){System.out.println(v+" ERR "+e+" "+(System.currentTimeMillis()-t));} } } }
